class ContentBrowserPage extends StatefulWidget {
  final String? contentType;
  final String title;
  final List<int> platformIds;
  const ContentBrowserPage({super.key, required this.title, this.contentType, this.platformIds = const []});
  @override State<ContentBrowserPage> createState() => _ContentBrowserPageState();
}

class _ContentBrowserPageState extends State<ContentBrowserPage> with SingleTickerProviderStateMixin {
  final repository = ContentRepository();
  final navigation = GalaxyNavigationSession.instance;
  final items = <ContentItem>[];
  late final AnimationController clock = AnimationController(vsync: this, duration: const Duration(seconds: 96))..repeat();
  bool loading = true;
  String query = '';
  int selected = 0;
  bool get snes => widget.contentType == 'game' && (widget.platformIds.contains(19) || widget.title.toUpperCase().contains('SNES'));
  List<ContentItem> get visible => items.where((x) => query.isEmpty || x.title.toLowerCase().contains(query.toLowerCase())).toList();
  @override void initState() { super.initState(); _load(); }
  @override void dispose() { clock.dispose(); super.dispose(); }
  void _publish() { if (visible.isEmpty) { navigation.clearContentNavigation(); return; } selected = selected.clamp(0, visible.length - 1); navigation.publishContentNavigation(DarkestWorldNavigationState(previous: selected > 0 ? visible[selected - 1] : null, current: visible[selected], next: selected + 1 < visible.length ? visible[selected + 1] : null, related: const [], source: 'archive', entryPoint: 'archive_browser')); }
  void _select(int value) { if (visible.isEmpty) return; setState(() => selected = value.clamp(0, visible.length - 1)); _publish(); }
  void _open(ContentItem item) => Navigator.of(context).push(MaterialPageRoute(builder: (_) => ContentDetailPage(item: item)));
  KeyEventResult _key(FocusNode _, KeyEvent event) { if (event is! KeyDownEvent || visible.isEmpty) return KeyEventResult.ignored; if (event.logicalKey == LogicalKeyboardKey.arrowLeft) { _select(selected - 1); return KeyEventResult.handled; } if (event.logicalKey == LogicalKeyboardKey.arrowRight) { _select(selected + 1); return KeyEventResult.handled; } if (event.logicalKey == LogicalKeyboardKey.enter) { _open(visible[selected]); return KeyEventResult.handled; } return KeyEventResult.ignored; }
  Future<void> _load() async { try { List<ContentItem> result; if (snes) { final rows = await supabase.from('storage_assets').select('id,title,public_url,metadata').eq('asset_type', 'snes_sealed').not('public_url', 'is', null).neq('public_url', '').order('title').limit(1000); result = [for (final row in rows) _asset(Map<String, dynamic>.from(row))]; } else { result = await repository.getContentItemsPage(type: widget.contentType, page: 0); } if (!mounted) return; setState(() { items.addAll(result); loading = false; }); _publish(); } catch (_) { if (mounted) setState(() => loading = false); } }
  ContentItem _asset(Map<String, dynamic> row) { final metadata = row['metadata'] is Map ? Map<String, dynamic>.from(row['metadata']) : <String, dynamic>{}; metadata['public_url'] = row['public_url']; return ContentItem.fromRow({'id': 'snes:${row['id']}', 'content_type': 'game', 'title': '${row['title'] ?? 'Untitled'}', 'slug': 'snes-${row['id']}', 'metadata': metadata}); }
  @override Widget build(BuildContext context) { final compact = MediaQuery.sizeOf(context).width < 900; return Focus(autofocus: true, onKeyEvent: _key, child: Scaffold(backgroundColor: const Color(0xFF010207), body: AnimatedBuilder(animation: clock, builder: (_, __) => Stack(children: [Positioned.fill(child: CustomPaint(painter: _VaultPainter(clock.value))), SafeArea(child: Padding(padding: EdgeInsets.fromLTRB(compact ? 12 : 28, compact ? 10 : 22, compact ? 12 : 28, 12), child: Column(children: [_Header(title: widget.title, compact: compact, onBack: () => Navigator.pop(context), onSearch: (value) { setState(() { query = value; selected = 0; }); _publish(); }), const SizedBox(height: 14), Expanded(child: loading ? const Center(child: CircularProgressIndicator()) : visible.isEmpty ? const Center(child: Text('GEEN CONTENT', style: TextStyle(letterSpacing: 3))) : ListView(children: [_VaultHero(items: visible, selected: selected, compact: compact, onSelect: _select, onOpen: _open), const SizedBox(height: 18), _ArchiveTelemetry(count: visible.length, selected: selected, query: query), const SizedBox(height: 12), _VaultGrid(items: visible, selected: selected, compact: compact, onSelect: _select, onOpen: _open), const SizedBox(height: 24)]))])))])))); }
}

class _Header extends StatelessWidget { final String title; final bool compact; final VoidCallback onBack; final ValueChanged<String> onSearch; const _Header({required this.title, required this.compact, required this.onBack, required this.onSearch}); @override Widget build(BuildContext context) => Row(children: [IconButton(onPressed: onBack, icon: const Icon(Icons.arrow_back_ios_new, size: 15)), Expanded(child: Column(crossAxisAlignment: CrossAxisAlignment.start, children: [Text(title.toUpperCase(), style: const TextStyle(fontSize: 12, letterSpacing: 2.8)), const SizedBox(height: 3), const Text('DARK CORE / PHYSICAL MEDIA VAULT / COLLECTION DECK', style: TextStyle(fontSize: 6.5, letterSpacing: 1.8, color: Color(0x65FFFFFF)))])), SizedBox(width: compact ? 145 : 280, height: 34, child: TextField(onChanged: onSearch, style: const TextStyle(fontSize: 10), decoration: const InputDecoration(hintText: 'SEARCH ARCHIVE', prefixIcon: Icon(Icons.search, size: 14), filled: true, fillColor: Color(0x700A0B14))))]); }

class _VaultHero extends StatelessWidget { final List<ContentItem> items; final int selected; final bool compact; final ValueChanged<int> onSelect; final ValueChanged<ContentItem> onOpen; const _VaultHero({required this.items, required this.selected, required this.compact, required this.onSelect, required this.onOpen}); @override Widget build(BuildContext context) { final current=items[selected]; final previous=selected>0?items[selected-1]:null; final next=selected+1<items.length?items[selected+1]:null; return Column(children: [Row(crossAxisAlignment:CrossAxisAlignment.start,children:[if(!compact)Expanded(child:_ShelfCase(item:previous,label:'PREVIOUS',onTap:previous==null?null:()=>onSelect(selected-1))),if(!compact)const SizedBox(width:10),Expanded(flex:compact?1:2,child:_FocusCase(item:current,compact:compact,onOpen:()=>onOpen(current))),if(!compact)const SizedBox(width:10),if(!compact)Expanded(child:_ShelfCase(item:next,label:'NEXT',onTap:next==null?null:()=>onSelect(selected+1)))]),if(compact)Padding(padding:const EdgeInsets.only(top:8),child:Row(children:[Expanded(child:_MiniNav(label:'PREVIOUS',enabled:previous!=null,onTap:previous==null?null:()=>onSelect(selected-1))),const SizedBox(width:8),Expanded(child:_MiniNav(label:'NEXT',enabled:next!=null,onTap:next==null?null:()=>onSelect(selected+1))) ]))]); } }

