class _VaultGrid extends StatelessWidget { final List<ContentItem> items; final int selected; final bool compact; final ValueChanged<int> onSelect; final ValueChanged<ContentItem> onOpen; const _VaultGrid({required this.items,required this.selected,required this.compact,required this.onSelect,required this.onOpen}); @override Widget build(BuildContext context)=>GridView.builder(shrinkWrap:true,physics:const NeverScrollableScrollPhysics(),itemCount:items.length,gridDelegate:SliverGridDelegateWithMaxCrossAxisExtent(maxCrossAxisExtent:220,mainAxisExtent:compact?260:286,crossAxisSpacing:12,mainAxisSpacing:12),itemBuilder:(_,i){final item=items[i];final active=i==selected;final url='${item.metadata['public_url']??item.metadata['image_url']??''}';return GestureDetector(onTap:()=>onSelect(i),onDoubleTap:()=>onOpen(item),child:AnimatedContainer(duration:const Duration(milliseconds:260),decoration:BoxDecoration(color:Color(active?0xE50A0A16:0xC8070810),border:Border.all(color:active?const Color(0x9D8B78B7):const Color(0x1DFFFFFF)),boxShadow:active?const[BoxShadow(color:Color(0x451E1439),blurRadius:28,offset:Offset(0,10))]:null),child:Stack(children:[Positioned.fill(child:CustomPaint(painter:_CaseBackdrop(selected:active))),Center(child:_PhysicalArtwork(url:url,title:item.title,large:active)),Positioned(left:9,right:9,bottom:9,child:Text(item.title,maxLines:2,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:8,letterSpacing:active?1.1:.2,fontWeight:active?FontWeight.w600:FontWeight.w400)))])));}); }

