class _CaseBackdrop extends CustomPainter { final bool selected; const _CaseBackdrop({required this.selected}); @override void paint(Canvas c,Size s){final rect=Offset.zero&s;c.drawRect(rect,Paint()..shader=RadialGradient(center:Alignment.center,radius:1.15,colors:[selected?const Color(0x201F1734):const Color(0x100C1621),const Color(0x00000000)]).createShader(rect));final p=Paint()..style=PaintingStyle.stroke..strokeWidth=.55..color=const Color(0x167F90A4);for(var i=0;i<5;i++){final inset=14+i*16.0;c.drawRRect(RRect.fromRectAndRadius(rect.deflate(inset),const Radius.circular(8)),p);}c.drawLine(0,s.height*.73,s.width,s.height*.73,p);} @override bool shouldRepaint(covariant _CaseBackdrop old)=>old.selected!=selected; }

class _VaultPainter extends CustomPainter { final double phase; const _VaultPainter(this.phase); @override void paint(Canvas c,Size s){final rect=Offset.zero&s;c.drawRect(rect,Paint()..shader=const RadialGradient(center:Alignment(0,-.2),radius:1.3,colors:[Color(0xFF1A1728),Color(0xFF080A12),Color(0xFF010207)]).createShader(rect));final rnd=math.Random(922);final center=Offset(s.width*.5,s.height*.42);for(var i=0;i<430;i++){final p=Offset(rnd.nextDouble()*s.width,rnd.nextDouble()*s.height);final z=.15+rnd.nextDouble();c.drawCircle(p,.25+z*.8,Paint()..color=Colors.white.withValues(alpha:.025+rnd.nextDouble()*.18));}final ring=Paint()..style=PaintingStyle.stroke..strokeWidth=.55..color=const Color(0x207F90A4);for(var i=0;i<7;i++){final w=s.width*(.22+i*.12);c.drawOval(Rect.fromCenter(center:center,width:w,height:w*.18),ring);}final sweep=(phase*math.pi*2)%(math.pi*2);c.drawArc(Rect.fromCenter(center:center,width:s.width*.78,height:s.width*.22),sweep,.7,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.1..color=const Color(0x557E93A6));final scan=(phase*s.height*1.35)%(s.height+140)-70;c.drawRect(Rect.fromLTWH(0,scan,s.width,1),Paint()..color=const Color(0x127F70B0));c.drawCircle(center,s.width*.08,Paint()..shader=const RadialGradient(colors:[Color(0x287D719F),Color(0x00000000)]).createShader(Rect.fromCircle(center:center,radius:s.width*.08)));c.drawRect(rect,Paint()..shader=RadialGradient(center:Alignment.center,radius:1.1,colors:[const Color(0x00000000),const Color(0x99000000)]).createShader(rect));} @override bool shouldRepaint(covariant _VaultPainter old)=>old.phase!=phase; }
